import { useAuthStore } from "../features/auth/store/useAuthStore";
import { apiClient } from "../shared/api/client"

let isRefreshing = false;
let failedQueue: any[] = [];

const processQueue = (error: any, token: string | null = null) => {
    failedQueue.forEach(prom => {
        if (error) {
            prom.reject(error);
        } else {
            prom.resolve(token);
        }
    });
    failedQueue = [];
}

export const axiosInterceptor = () => {
    apiClient.interceptors.request.use(
        (config) => {
            const token = useAuthStore.getState().accessToken;
            if (token && config.headers) {
                config.headers["Authorization"] = `Bearer ${token}`;
            }
            return config;
        },
        (error) => {
            return Promise.reject(error);
        }
    );

    apiClient.interceptors.response.use(
        (response) => response,
        async (error) => {
            const originalRequest = error.config;

            if (error.response?.status === 401 && !originalRequest._retry) {
                if (isRefreshing) {
                    return new Promise((resolve, reject) => {
                        failedQueue.push({ resolve, reject });
                    }).then(token => {
                        originalRequest.headers.Authorization = `Bearer ${token}`;
                        return apiClient(originalRequest);
                    }).catch(error => {
                        return Promise.reject(error);
                    });
                }

                originalRequest._retry = true;
                isRefreshing = true;

                const { refreshAccessToken } = useAuthStore.getState();

                try {
                    await refreshAccessToken();
                    const newToken = useAuthStore.getState().accessToken;

                    processQueue(newToken);

                    if (newToken) {
                        originalRequest.headers.Authorization = `Bearer ${newToken}`;
                    }
                    return apiClient(originalRequest);
                } catch (refreshError) {
                    processQueue(refreshError, null);

                    const { logout } = useAuthStore.getState();
                    await logout();

                    window.location.href = "/login";

                    return Promise.reject(refreshError);
                } finally {
                    isRefreshing = false;
                }
            }

            return Promise.reject(error);
        }
    );
}

import type { User } from "../../types/auth.types";
import TableData from "../../../../shared/ui/TableData";
import UserRow from "./UserRow";

interface TableUserPros {
    currentData: User[];
    selectedData: string[];
    handleSelectAll: () => void;
    handleSelectData: (userId: string) => void;
}

const TableUser: React.FC<TableUserPros> = ({ currentData, selectedData, handleSelectAll, handleSelectData }) => {

    const theader = [
        "[USER_IDENT]",
        "[CONTACT_NET]",
        "[SYS_ROLE]",
        "[SYS_STATUS]",
        "[CREATION_CYCLE]",
        "[EXEC]"
    ];

    return (
        <>
            <TableData theader={theader} Data={currentData} selectedData={selectedData} handleSelectAll={handleSelectAll}>
                {currentData && currentData.length > 0 ? (
                    currentData?.map((user: any) => (
                        <UserRow key={user.id} user={user} selectedData={selectedData} handleSelectData={handleSelectData} />
                    ))
                ) : (
                    <tr>
                        <td colSpan={7} className="p-12 text-center border-b border-zinc-800 bg-black">
                            <p className="text-[#ff0055] text-[10px] font-bold tracking-[0.2em] uppercase">[SYS_NO_USERS_FOUND: DATABASE_EMPTY_OR_FILTER_MISMATCH]</p>
                        </td>
                    </tr>
                )}
            </TableData>
        </>
    );
};

export default TableUser;

import { MdBlock, MdCheckCircle, MdEmail, MdPhone, MdVerifiedUser } from "react-icons/md";
import type { User } from "../../types/auth.types";
import { FaCheck } from "react-icons/fa";

import { useNavigate } from "react-router-dom";
import moment from "moment";
import { useAuthStore } from "../../store/useAuthStore";
import { useDeleteMutation, useToggleActiveMutation } from "../../hooks/mutation/useAuthMutation";
import { BiEdit, BiTrash } from "react-icons/bi";
import SweetAlertas from "../../../../shared/ui/SweetAlertas";

interface UserRowProps {
    user: User;
    selectedData: string[];
    handleSelectData: (id: string) => void;
}
const UserRow: React.FC<UserRowProps> = ({ user, selectedData, handleSelectData }) => {
    const navigate = useNavigate();
    const { accessToken } = useAuthStore();
    const deleteMutation = useDeleteMutation();
    const toggleActiveMutation = useToggleActiveMutation();

    const Cancel = () => { };

    const ConfirmDeleteBlog = (id: string) => {
        deleteMutation.mutateAsync({ id: id, adminToken: accessToken! });
    };

    const handleDelete = (id: string) => {
        SweetAlertas.OnDialogChoose({
            message: `Estas seguro de eliminar el usuario ${user?.username}`,
            onConfirm: () => ConfirmDeleteBlog(id),
            onCancel: Cancel,
        });
    };

    const handleToggleActive = (userId: string) => {
        toggleActiveMutation.mutateAsync({ id: userId, adminToken: accessToken! });
    };

    const getRoleBadge = (role: string) => {
        const styles = {
            ADMIN: "bg-[#ff0055]/10 text-[#ff0055] border-[#ff0055]/50",
            SUPER_ADMIN: "bg-[#00f0ff]/10 text-[#00f0ff] border-[#00f0ff]/50",
            USER: "bg-[#e4ff00]/10 text-[#e4ff00] border-[#e4ff00]/50"
        };

        const labels = {
            ADMIN: "[ADMIN]",
            SUPER_ADMIN: "[SUPER_ADMIN]",
            USER: "[USER]"
        };

        return (
            <span
                className={`px-2 py-1 uppercase tracking-widest text-[10px] font-mono border ${styles[role as keyof typeof styles]}`}
            >
                {labels[role as keyof typeof labels]}
            </span>
        );
    };

    return (
        <tr
            key={user?.id}
            className="text-center border-b border-zinc-800 bg-[#050505] hover:bg-[#00f0ff]/5 transition-colors group"
        >
            <td className="px-6 py-4">
                <label className="flex gap-3 items-center cursor-pointer relative justify-center">
                    <input type="checkbox" checked={selectedData.includes(user?.id!)} onChange={() => handleSelectData(user?.id!)} className="hidden peer" />
                    <span className="w-4 h-4 border border-zinc-600 bg-black relative flex items-center justify-center peer-checked:border-[#00f0ff] peer-checked:bg-[#00f0ff]/20 transition-all rounded-none"></span>
                    <FaCheck size={10} className="absolute hidden peer-checked:inline top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-[#00f0ff]" />
                </label>
            </td>
            <td className="px-6 py-4">
                <div className="flex items-center justify-start gap-3">
                    <img
                        src={user?.avatar || "https://via.placeholder.com/40"}
                        alt={user?.username || "User"}
                        className="w-10 h-10 object-cover border border-zinc-700 group-hover:border-[#00f0ff] transition-colors rounded-none grayscale group-hover:grayscale-0"
                    />
                    <div className="text-left">
                        <p className="text-white font-mono uppercase tracking-widest text-[11px]">
                            {user?.firstName} {user?.lastName}
                        </p>
                        <p className="text-zinc-500 font-mono text-[10px]">
                            @{user?.username && user.username.length > 20
                                ? `${user.username.substring(0, 20)}...`
                                : user.username}
                        </p>
                    </div>
                </div>
            </td>
            <td className="px-6 py-4">
                <div className="space-y-1 font-mono">
                    <div className="flex items-center gap-2 text-zinc-400 text-[10px] uppercase tracking-widest">
                        <MdEmail size={12} className="text-[#00f0ff]" />
                        {user?.email}
                        {user?.emailVerified && (
                            <MdVerifiedUser
                                size={12}
                                className="text-[#e4ff00]"
                                title="Email verificado"
                            />
                        )}
                    </div>
                    {user.phone && (
                        <div className="flex items-center gap-2 text-zinc-500 text-[10px] uppercase tracking-widest">
                            <MdPhone size={12} className="text-[#00f0ff]" />
                            {user.phone}
                        </div>
                    )}
                </div>
            </td>
            <td className="flex-1 m-auto px-6 py-4">{getRoleBadge(user?.role!)}</td>
            <td className="flex-1 justify-items-center items-center">
                <button
                    onClick={() => handleToggleActive(user?.id!)}
                    className={`flex items-center justify-center gap-2 px-2 py-1 font-mono uppercase tracking-widest text-[10px] transition-all cursor-pointer border ${user?.isActive
                        ? "bg-[#00f0ff]/10 text-[#00f0ff] border-[#00f0ff]/50 hover:bg-[#00f0ff]/20"
                        : "bg-[#ff0055]/10 text-[#ff0055] border-[#ff0055]/50 hover:bg-[#ff0055]/20"
                        }`}
                >
                    {user.isActive ? (
                        <>
                            <MdCheckCircle size={12} />
                            [ACTIVE]
                        </>
                    ) : (
                        <>
                            <MdBlock size={12} />
                            [INACTIVE]
                        </>
                    )}
                </button>
            </td>
            <td className="px-6 py-4">
                <p className="text-zinc-500 font-mono text-[10px] uppercase tracking-widest">
                    {moment(user.createdAt).format("DD/MM/YYYY")}
                </p>
            </td>
            <td className="px-6 py-4">
                <div className="flex mx-auto items-center justify-center gap-2">
                    <button
                        onClick={() => navigate(`/dashboard/users/${user.id}/edit`)}
                        className="p-2 border border-zinc-700 bg-transparent text-zinc-400 hover:border-[#00f0ff] hover:text-[#00f0ff] transition-all"
                    >
                        <BiEdit size={16} />
                    </button>
                    <button
                        onClick={() => handleDelete(user?.id!)}
                        className="p-2 border border-zinc-700 bg-transparent text-zinc-400 hover:border-[#ff0055] hover:text-[#ff0055] transition-all"
                    >
                        <BiTrash size={16} />
                    </button>
                </div>
            </td>
        </tr>
    );
};

export default UserRow;

import { useMutation, useQueryClient } from "@tanstack/react-query";
import type { DeleteUserProps, RegisterRequest, UpdateUserProps } from "../../types/auth.types";
import { authService } from "../../services/authService";
import { toast } from "sonner";
import type { ChangePasswordInput } from "../../../profile/types/profile.types";

export const useAuthRegisterMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: (auth: RegisterRequest) => authService.register(auth),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Usuario creado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al crear el usuario");
        }
    })
}

export const useDeleteMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ id, adminToken }: DeleteUserProps) => authService.deleteUser({ id, adminToken }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Usuario eliminado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al eliminar el usuario");
        }
    })
}

export const useDeleteUsersMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ ids, adminToken }: DeleteUserProps) => authService.deleteUsers({ ids, adminToken }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Usuarios eliminados exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al eliminar los usuarios");
        }
    })
}

export const useToggleActiveMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ id, adminToken }: DeleteUserProps) => authService.toggleActiveUser({ id, adminToken }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Usuario activado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al activar el usuario");
        }
    })
}

export const useUpdateUserMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ id, userData }: UpdateUserProps) => authService.updateUser({ id, userData }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            queryClient.invalidateQueries({
                queryKey: ['profile']
            });
            toast.success(response.message || "Usuario actualizado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al actualizar el usuario");
        }
    })
}

export const useForgotPasswordMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: (email: string) => authService.forgotPassword(email),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Correo enviado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al enviar el correo");
        }
    })
}

export const useChangePasswordClientMutation = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ email, otp, password }: ChangePasswordInput) => authService.changePasswordClient({ email, otp, password }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({
                queryKey: ['users']
            });
            toast.success(response.message || "Contraseña cambiada exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al cambiar la contraseña");
        }
    })
}

import { useDeleteUsersMutation } from "./mutation/useAuthMutation";
import { useAuthStore } from "../store/useAuthStore";

export const useDataActions = (Data: any[] | undefined, selectedData: string[], setSelectedData: React.Dispatch<React.SetStateAction<string[]>>) => {
    const deleteSelectMutation = useDeleteUsersMutation();
    const { accessToken } = useAuthStore();

    const handleSelectAll = () => {
        if (!Data) return;
        if (selectedData.length === Data.length) {
            setSelectedData([]);
        } else {
            setSelectedData(Data.map((u: any) => u.id));
        }
    }

    const handleSelectData = (userId: string) => {
        setSelectedData((prev) =>
            prev.includes(userId)
                ? prev.filter((id) => id !== userId)
                : [...prev, userId]
        );
    };

    const handleBulkDelete = () => {
        if (confirm(`¿Estás seguro de eliminar ${selectedData.length} usuario(s)?`)) {
            deleteSelectMutation.mutateAsync({ ids: selectedData, adminToken: accessToken! });
            setSelectedData([]);
        }
    };

    return {
        selectedData,
        handleSelectAll,
        handleSelectData,
        handleBulkDelete
    }
}

import { useNavigate, useParams } from "react-router-dom";
import { useUser } from "../../hooks/queries/useUsers";
import useInputs from "../../../../shared/hooks/useInputs";
import { useEffect, useState } from "react";
import Sidebar from "../../../dashboard/components/Sidebar";
import BreadCrumbs from "../../../../shared/ui/BreadCrumbs";
import NavMobile from "../../../dashboard/components/NavMobile";
import ButtonMobile from "../../../../shared/ui/ButtonMobile";
import DashHeader from "../../../../shared/ui/DashHeader";
import { BiUser } from "react-icons/bi";
import HeaderAction from "../../components/UserCreate/HeaderAction";
import FormInfoPersonal from "../../components/UserCreate/FormInfoPersonal";
import FormAvatar from "../../components/UserCreate/FormAvatar";
import FormRoleAndState from "../../components/UserCreate/FormRoleAndState";
import { useUpdateUserMutation } from "../../hooks/mutation/useAuthMutation";
import { AxiosError } from "axios";

interface ValidationErrors {
    [key: string]: string[];
}

const DashEditUserPage = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [isMenuOpen, setIsMenuOpen] = useState<boolean>(false);
    const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
    const updateUserMutation = useUpdateUserMutation();
    const { data } = useUser(id!);

    const [userData, onChangeCreateData, setUserData] = useInputs({
        email: "",
        password: "",
        username: "",
        firstName: "",
        lastName: "",
        phone: "",
        avatar: "",
        role: "USER",
        isActive: true,
        emailVerified: false,
    });

    useEffect(() => {
        if (data) {
            setUserData({
                email: data.email,
                username: data.username,
                firstName: data.firstName,
                lastName: data.lastName,
                phone: data.phone,
                avatar: data.avatar,
                role: data.role,
                isActive: data.isActive,
                emailVerified: data.emailVerified,
            })
        }
    }, [data])

    const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});

    const getFieldsError = (fieldName: string): string | undefined => {
        return validationErrors[fieldName]?.[0];
    }

    const handleSubmit = async (e?: React.MouseEvent<HTMLButtonElement>) => {
        e?.preventDefault();
        setValidationErrors({});
        setIsSubmitting(true);

        try {
            await updateUserMutation.mutateAsync({ id: id!, userData });
            navigate('/dashboard/users');
        } catch (error) {
            if (error instanceof AxiosError && error.response?.data?.errors) {
                setValidationErrors(error.response.data.errors);
            }
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <div className="min-h-screen bg-[#020202] text-white font-mono selection:bg-[#00f0ff] selection:text-black">
            <div className="flex">
                {/**Sidebar */}
                <Sidebar />

                <div className="flex flex-col flex-1">
                    <div className="max-w-7xl px-0 md:px-9">
                        <BreadCrumbs />
                    </div>

                    {/* MObile Menu */}
                    <NavMobile
                        isMenuOpen={isMenuOpen}
                        setIsMenuOpen={setIsMenuOpen}
                    />

                    <div className="w-full mx-auto flex-1 px-8 md:px-12 pb-8">
                        <ButtonMobile isMenuOpen={isMenuOpen}
                            setIsMenuOpen={setIsMenuOpen}
                        />

                        {/* Header */}
                        <DashHeader data={[]} title="Editar Usuario" titleData="Usuarios" path="users" titleIcon={<BiUser className="text-cyan-400" size={36} />} list={false} />
                        <HeaderAction isSubmitting={isSubmitting} handleSubmit={handleSubmit} />

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                            <div className="lg:col-span-2 space-y-6">
                                {/* Información Personal */}
                                <FormInfoPersonal
                                    userData={userData}
                                    onChangeCreateData={onChangeCreateData}
                                    setUserData={setUserData}
                                    getFieldsError={getFieldsError}
                                />

                                {/* Avatar */}
                                <FormAvatar
                                    userData={userData}
                                    onChangeCreateData={onChangeCreateData}
                                />
                            </div>

                            {/* Right Sidebar */}
                            <FormRoleAndState
                                userData={userData}
                                onChangeCreateData={onChangeCreateData}
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DashEditUserPage;

