import { useEffect, useState } from "react";
import { useUsers } from "../../hooks/queries/useUsers";
import TableUser from "../../components/ListUser/TableUser";
import Pagination from "../../../../shared/ui/Pagination";
import Sidebar from "../../../dashboard/components/Sidebar";
import BreadCrumbs from "../../../../shared/ui/BreadCrumbs";
import NavMobile from "../../../dashboard/components/NavMobile";
import ButtonMobile from "../../../../shared/ui/ButtonMobile";
import DashHeader from "../../../../shared/ui/DashHeader";
import BulkAction from "../../../../shared/ui/BulkAction";
import { useDataActions } from "../../hooks/useDataActions";
import UserFilters from "../../components/ListUser/UserFilters";
import { BiUser } from "react-icons/bi";

const DashListUserPage = () => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const [filterRole, setFilterRole] = useState<string>("all");
    const [showFilters, setShowFilters] = useState(false);
    const [isActive, setIsActive] = useState<boolean | null>(null);
    const [selectedUsers, setSelectedUsers] = useState<string[]>([]);
    const [currentPage, setCurrentPage] = useState(1);
    let itemsPerPage = 10;

    useEffect(() => {
        setCurrentPage(1);
    }, [searchTerm, filterRole, isActive]);

    const { data: users } = useUsers({
        search: searchTerm,
        isActive: isActive === null ? undefined : isActive,
        role: filterRole === "all" ? undefined : filterRole
    });

    // Calcular índices para "cortar" la lista
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;

    // Estos son los usuarios que vas a mostrar en la tabla (IMPORTANTE)
    const currentUsers = users?.slice(indexOfFirstItem, indexOfLastItem) || [];

    // Handlers
    const { handleSelectAll, handleSelectData, handleBulkDelete } = useDataActions(users, selectedUsers, setSelectedUsers);

    return (
        <div className="min-h-screen bg-[#020202] text-white font-mono selection:bg-[#00f0ff] selection:text-black">
            <div className="flex">
                {/** Sidebar */}
                <Sidebar />

                <div className="flex flex-col flex-1">
                    <div className="max-w-7xl px-0 md:px-9">
                        <BreadCrumbs />
                    </div>

                    {/* Mobile Menu */}
                    <NavMobile isMenuOpen={isMenuOpen} setIsMenuOpen={setIsMenuOpen} />

                    <div className="w-full mx-auto flex-1 px-8 md:px-12 pb-8">
                        <ButtonMobile
                            isMenuOpen={isMenuOpen}
                            setIsMenuOpen={setIsMenuOpen}
                        />

                        {/* Header */}
                        <DashHeader
                            data={users}
                            title="Gestion de Usuarios"
                            titleData="Usuario"
                            path="users"
                            titleIcon={<BiUser className="text-cyan-400" size={36} />}
                            list={true}
                        />

                        {/* Search and Filters Bar */}
                        <UserFilters
                            searchTerm={searchTerm}
                            setSearchTerm={setSearchTerm}
                            filterRole={filterRole}
                            setFilterRole={setFilterRole}
                            showFilters={showFilters}
                            setShowFilters={setShowFilters}
                            isActive={isActive}
                            setIsActive={setIsActive}
                        />

                        {/* Bulk Actions */}
                        {selectedUsers.length > 0 && (
                            <BulkAction
                                selectedData={selectedUsers}
                                title="usuarios"
                                handleBulkDelete={handleBulkDelete}
                            />
                        )}

                        <div className="w-72 sm:w-[500px] md:w-[420px] lg:w-[680px] xl:w-full 2xl:w-full bg-[#050505] border border-zinc-800 relative">
                            <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-[#00f0ff] opacity-50 pointer-events-none" />
                            <div className="absolute bottom-0 left-0 w-2 h-2 border-b border-l border-[#00f0ff] opacity-50 pointer-events-none" />
                            <div className="overflow-x-auto">
                                <TableUser
                                    currentData={currentUsers}
                                    selectedData={selectedUsers}
                                    handleSelectAll={handleSelectAll}
                                    handleSelectData={handleSelectData} />
                            </div>

                            {/* Pagination */}
                            <Pagination
                                itemsPerPage={itemsPerPage}
                                currentPage={currentPage}
                                setCurrentPage={setCurrentPage}
                                indexOfFirstItem={indexOfFirstItem}
                                indexOfLastItem={indexOfLastItem}
                                data={users}
                                title="usuarios" />
                        </div>
                    </div>
                </div>
            </div>
        </div>

    );
};

export default DashListUserPage;

import React, { useEffect, useState } from "react";
import { FaFacebook, FaGoogle } from "react-icons/fa";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { CiLogin } from "react-icons/ci";
import { useAuthStore } from "../../store/useAuthStore";

const LoginPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [email, setEmail] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  const [rememberMe, setRememberMe] = useState<boolean>(false);

  const { login, isAuthenticated, clearError } = useAuthStore();
  const from = (location.state as any)?.from?.pathname || '/dashboard';

  // Redirigir si ya está autenticado
  useEffect(() => {
    if (isAuthenticated) {
      navigate(from, { replace: true });
    }
  }, [isAuthenticated, navigate]);

  // Limpiar error al desmontar
  useEffect(() => {
    return () => {
      clearError();
    };
  }, [clearError]);

  const handleSocialLogin = (provider: string) => {
    console.log(`Login with ${provider}`);
  };

  const handleSubmit = async (e?: React.MouseEvent<HTMLButtonElement>) => {
    e?.preventDefault();

    try {
      const response = await login({ email, password });
      console.log(response);
    } catch (error) {
      console.log(error);
    }
  }

  return (
    <div className="min-h-screen bg-[#020202] relative font-mono text-white flex items-center justify-center p-4">
      {/* Background Grid Pattern */}
      <div
        className="fixed inset-0 pointer-events-none opacity-[0.03] z-0"
        style={{
          backgroundImage: `
            linear-gradient(to right, #ffffff 1px, transparent 1px),
            linear-gradient(to bottom, #ffffff 1px, transparent 1px)
