    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ id, payment }: UpdatePaymentInput) => paymentService.updatePayment({ id, payment }),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['payment'] });
