        <span className="w-1.5 h-1.5 bg-[#00f0ff] inline-block"></span>
        [ETIQUETAS_DE_PRODUCTO]
      </h2>

      <div className="space-y-3">
        <div className="flex gap-2">
          <input
            type="text"
            value={newTag}
            onChange={(e) => setNewTag(e.target.value)}
