            placeholder="[ADD_TAG]"
          />
          <button
            type="button"
            onClick={addTag}
            className="bg-[#00f0ff]/10 border border-[#00f0ff] text-[#00f0ff] hover:bg-[#00f0ff] hover:text-black transition-all flex justify-center items-center px-4 py-3 min-w-[48px]"
