import { useMutation, useQueryClient } from "@tanstack/react-query";
import { productService } from "../../services/productService";
import { queryKeys } from "../../../../shared/lib/queryClient";
import { toast } from "sonner";
import { handleApiError } from "../../../../shared/lib/errorHandler";

export const useCreateProductMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (product: FormData) => productService.create(product),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            toast.success(response.message || "Producto creado exitosamente");
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al crear el producto')
        }
    })
}

export const useUpdateProductMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ id, data }: { id: string, data: FormData }) => productService.update(id, data),
        onSuccess: (response, variables) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            queryClient.invalidateQueries({
                queryKey: ['products', variables.id]
            });

            if (queryKeys?.products?.detail) {
                queryClient.setQueryData(
                    queryKeys.products.detail(variables.id),
                    response.data || response
                );
            }

            toast.success(response.message || "Producto actualizado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al actualizar el producto");
        }
    })
}

export const useUpdatePublishProductMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ id, isPublished }: { id: string, isPublished: boolean }) => productService.updatePublish(id, isPublished),
        onSuccess: (response, variables) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            queryClient.invalidateQueries({
                queryKey: ['products', variables.id]
            });

            if (queryKeys?.products?.detail) {
                queryClient.setQueryData(
                    queryKeys.products.detail(variables.id),
                    response.data || response
                );
            }

            toast.success(response.message || "Producto actualizado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al actualizar el producto");
        }
    })
}

export const useDeleteProductMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (id: string) => productService.delete(id),
        onSuccess: (response) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            toast.success(response.message || "Producto eliminado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al eliminar el producto");
        }
    })
}

export const useDeleteManyProductsMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (ids: string[]) => productService.deleteMany(ids),
        onSuccess: (response) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            toast.success(response.message || "Productos eliminados exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al eliminar los productos");
        }
    })
}

export const useAnalyzeTitleMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (title: string) => productService.analyzeTitle(title),
        onSuccess: (response) => {
            queryClient.invalidateQueries({ queryKey: ['products'] });

            toast.success(response.message || "Título analizado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al analizar el título");
        }
    })
}

import { useInfiniteQuery, useQuery } from "@tanstack/react-query";
import type { ProductFilters } from "../../types/product.types";
import { productService } from "../../services/productService";
import { queryKeys } from "../../../../shared/lib/queryClient";

export const useProducts = (filters?: ProductFilters) => {
    return useQuery({
        queryKey: queryKeys.products.list(filters),
        queryFn: () => productService.getAll(filters),
        select: (response) => response.data,
        staleTime: 2 * 60 * 1000,
    })
}

export const useProduct = (id: string) => {
    return useQuery({
        queryKey: queryKeys.products.detail(id),
        queryFn: () => productService.getById(id),
        select: (response) => response.data,
        enabled: !!id,
    })
}

export const useProductByBrand = () => {
    return useQuery({
        queryKey: ['brands'],
        queryFn: async () => {
            const response = await productService.getAll()
            const brands = [...new Set(response.data.map((product) => product.brand))];
            return brands.sort();
        },
        staleTime: 10 * 60 * 1000,
    })
}

export const useProductBySlug = (slug: string) => {
    return useQuery({
        queryKey: queryKeys.products.bySlug(slug),
        queryFn: () => productService.getBySlug(slug),
        select: (response) => response.data,
        enabled: !!slug,
    })
}

export const useCategories = () => {
    return useQuery({
        queryKey: ['categories'],
        queryFn: async () => {
            const response = await productService.getAll();
            const categories = [...new Set(response.data.map(p => p.category))];
            return categories.sort();
        },
        staleTime: 10 * 60 * 1000,
    });
};

export const useProductsInfiniteQuery = (filters?: any) => {
    return useInfiniteQuery({
        queryKey: queryKeys.products.list(filters),
        queryFn: ({ pageParam = 0 }) => productService.getAll({ ...filters, limit: 10, offset: pageParam }),
        getNextPageParam: (lastPage, allPages) => {
            if (lastPage.data && lastPage.data.length === 10) {
                return allPages.length * 10;
            }
            return undefined;
        },
        initialPageParam: 0,
    })
}

import { useDeleteManyProductsMutation } from "./mutation/useProductMutation";

export const useDataActions = (Data: any[] | undefined, selectedData: string[], setSelectedData: React.Dispatch<React.SetStateAction<string[]>>) => {
    const deleteSelectMutation = useDeleteManyProductsMutation();

    const handleSelectAll = () => {
        if (!Data) return;
        if (selectedData.length === Data.length) {
            setSelectedData([]);
        } else {
            setSelectedData(Data.map((u: any) => u.id));
        }
    }

    const handleSelectData = (userId: string) => {
        setSelectedData((prev) =>
            prev.includes(userId)
                ? prev.filter((id) => id !== userId)
                : [...prev, userId]
        );
    };

    const handleBulkDelete = () => {
        if (confirm(`¿Estás seguro de eliminar ${selectedData.length} producto(s)?`)) {
            deleteSelectMutation.mutateAsync(selectedData);
            setSelectedData([]);
        }
    };

    return {
        selectedData,
        handleSelectAll,
        handleSelectData,
        handleBulkDelete
    }
}

