import React, { useEffect, useState } from "react";
import { FaStar } from "react-icons/fa";
import { IoIosAdd } from "react-icons/io";
import { RiSubtractFill } from "react-icons/ri";
import { BsCartCheck, BsCartPlus } from "react-icons/bs";
import TabsSection from "../../components/detailsProduct/TabsSection";
import BreadCrumbs from "../../../../shared/ui/BreadCrumbs";
import { useProductBySlug } from "../../hook/queries/useProduct";
import { useParams } from "react-router-dom";
import LoadingFallback from "../../../../shared/ui/LoadingFallback";
import { useCartAddMutation } from "../../../cart/hook/mutation/useCartMutation";
import { BiHeart } from "react-icons/bi";
import { useWishlistAddMutation } from "../../../wishlist/hook/mutation/useWishlistMutation";
import type { Product } from "../../types/product.types";

const DetailsPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const useCartMutation = useCartAddMutation();
  const addWishlistItem = useWishlistAddMutation();
  const { data: product, isLoading, error } = useProductBySlug(slug!);
  const [thumbnail, setThumbnail] = useState<string>();
  const [quantity, setQuantity] = useState(1);

  const handleIncrement = () => {
    product?.stock!
    if (quantity < product?.stock!) {
      setQuantity(quantity + 1);
    }
  };

  const handleDecrement = () => {
    if (quantity > 1) {
      setQuantity(quantity - 1);
    }
  };

  useEffect(() => {
    // Solo actualiza si el producto está cargado y tiene imágenes
    if (product && product.images && product.images.length > 0) {
      setThumbnail(product.images[0].url);
    }
  }, [product]);

  const handleAddToCart = async () => {
    await useCartMutation.mutateAsync({
      productId: product?.id!,
      quantity: quantity,
      name: product?.name!,
      image: product?.images![0].url!,
      price: product?.price!,
      discount: product?.priceDiscount!,
      stock: product?.stock!,
    });
  };

  const handleAddToWishlist = async (item: Product) => {
    await addWishlistItem.mutateAsync({
      productId: item.id,
      productName: item.name,
      productImage: item.images![0].url!,
      price: item.price,
      discount: item.priceDiscount!,
      category: item.slug,
      stock: item.stock,
      reviews: item?.reviewsCount!,
      rating: item?.rating!,
      total: item.price - (item.price * item.priceDiscount!) / 100
    });
  };

  if (isLoading) {
    return <LoadingFallback />;
  }

  if (error) {
    return <div>Error: {error.message}</div>;
  }

  if (!product) return <div>Producto no encontrado</div>;

  return (
    <div className="min-h-screen bg-[#020202] relative font-mono text-white">
      {/* Elemento decorativo de fondo */}
      <div
        className="fixed inset-0 pointer-events-none opacity-[0.03] z-0"
        style={{
          backgroundImage: `
            linear-gradient(to right, #ffffff 1px, transparent 1px),
            linear-gradient(to bottom, #ffffff 1px, transparent 1px)
          `,
          backgroundSize: '40px 40px'
        }}
      />
      {/* Breadcrumb */}
      <div className="max-w-7xl mx-auto relative z-10">
        <BreadCrumbs />
      </div>

      {/* Main Product Section */}
      <div className="max-w-7xl mx-auto w-full px-4 sm:px-6 py-10 relative z-10">
        <div className="flex flex-col lg:flex-row gap-12 relative">
          <BiHeart size={32}
            onClick={() => handleAddToWishlist(product)}
            className="absolute top-0 right-0 z-50 text-zinc-500 hover:text-[#ff0055] transition-colors cursor-pointer bg-black/50 p-1.5 border border-transparent hover:border-[#ff0055]" />
          {/* Image Gallery */}
          <div className="flex flex-col-reverse md:flex-row gap-4 lg:w-1/2">
            {/* Thumbnails */}
            <div className="flex md:flex-col gap-3 overflow-x-auto md:overflow-visible custom-scrollbar pb-2 md:pb-0">
              {product?.images!.map((image: { url: string }, index: number) => (
                <div
                  key={index}
                  onClick={() => setThumbnail(image.url)}
                  className={`relative w-20 h-20 overflow-hidden cursor-pointer transition-all border ${thumbnail === image.url
                    ? "border-[#00f0ff] opacity-100"
                    : "border-zinc-800 opacity-60 hover:opacity-100 hover:border-[#00f0ff]/50"
                    }`}
                >
                  <img
                    src={image.url}
                    alt={`Thumbnail ${index + 1}`}
                    className="w-full h-full object-cover grayscale opacity-80 hover:grayscale-0 hover:opacity-100 transition-all duration-300"
                  />
                  {thumbnail === image.url && (
                    <div className="absolute inset-0 bg-[#00f0ff]/10 pointer-events-none" />
                  )}
                </div>
              ))}
            </div>

            {/* Main Image */}
            <div className="w-full aspect-square md:w-[480px] md:h-[480px] flex-1 border border-zinc-800 bg-[#050505] relative overflow-hidden group">
              <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-[#00f0ff] opacity-50 z-20" />
              <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-[#00f0ff] opacity-50 z-20" />

              {/* Scanline subtle */}
              <div className="absolute inset-0 bg-[linear-gradient(transparent_50%,rgba(0,240,255,0.03)_50%)] bg-[length:100%_4px] z-10 pointer-events-none" />

              <img
                src={thumbnail}
                alt="Selected product"
                className="w-full h-full object-contain relative z-0 transition-transform duration-500 group-hover:scale-105"
              />
            </div>
          </div>

          {/* Product Info */}
          <div className="lg:w-1/2 flex flex-col pt-2">
            <h1 className="text-3xl sm:text-4xl text-white font-bold mb-4 uppercase tracking-widest leading-tight" style={{ fontFamily: "'Rajdhani', sans-serif" }}>
              {product?.name}
            </h1>

            {/* Rating */}
            <div className="flex items-center gap-1 mb-6">
              <span className="text-[#00f0ff] text-[10px] uppercase tracking-widest bg-[#00f0ff]/10 border border-[#00f0ff]/30 px-2 py-0.5 mr-2">
                CALIFICACION_DEL_SISTEMA
              </span>
              {Array(5)
                .fill("")
                .map((_, i: number) => (
                  <FaStar
                    key={i}
                    size={14}
                    className={
                      product?.rating! > i
                        ? "text-[#e4ff00]"
                        : "text-zinc-700"
                    }
                  />
                ))}
              <p className="text-[10px] ml-2 text-zinc-400 font-bold tracking-widest">
                [ {product?.rating}.0 ]
              </p>
            </div>

            {/* Price section */}
            <div className="mb-8 border border-zinc-800 bg-[#050505] p-6 relative">
              <div className="absolute top-0 right-0 px-2 py-1 bg-black border-l border-b border-zinc-800 text-[10px] text-zinc-500 uppercase tracking-widest">
                DATOS_FINANCIEROS //
              </div>

              <div className="flex flex-col gap-1 mt-2">
                {product?.priceDiscount ? (
                  <div className="flex items-center gap-3">
                    <p className="text-zinc-500 line-through text-xs font-mono uppercase tracking-widest">
                      CR_{product?.price}
                    </p>
                    <div className="bg-[#e4ff00] text-black px-2 py-0.5 text-[10px] font-bold tracking-widest uppercase">
                      -{product?.priceDiscount}%
                    </div>
                  </div>
                ) : null}

                <p className="text-4xl font-bold text-[#00f0ff] font-mono tracking-wider mt-1">
                  CR_{Math.round(
                    product?.price! - (product?.price! * (product?.priceDiscount || 0)) / 100
                  )}
                </p>

                <span className="text-zinc-600 text-[10px] uppercase tracking-widest mt-2 border-t border-zinc-800 border-dashed pt-2 inline-block">
                  [IMPUESTOS_INCLUIDOS]
                </span>
              </div>
            </div>

            {/* About the product - placeholder layout for future use if description exists in product object otherwise leave empty spaces */}
            <div className="mb-8">
              <h3 className="text-[#e4ff00] text-xs font-bold tracking-[0.2em] uppercase mb-4 flex items-center gap-2">
                <span className="w-1.5 h-1.5 bg-[#e4ff00] animate-pulse"></span>
                ESPECIFICACIONES_DEL_PRODUCTO //
              </h3>
              <div className="space-y-2 text-zinc-400 text-sm border-l-2 border-zinc-800 pl-4">
                <p className="font-mono text-xs uppercase tracking-widest text-[#00f0ff] mb-1">NO_HAY_ESPECIFICACIONES</p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-6 mt-auto border-t border-zinc-800 pt-8">
              {/* Quantity Selector */}
              <div className="flex flex-col gap-2">
                <span className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">CANTIDAD_A_SELECCIONAR</span>
                <div className="w-32 h-12 border border-zinc-600 bg-black flex justify-between items-center group">
                  <button
                    onClick={handleDecrement}
                    className="w-10 h-full flex items-center justify-center text-zinc-400 hover:text-[#00f0ff] hover:bg-zinc-900 border-r border-zinc-800 transition-colors"
                  >
                    <RiSubtractFill size={16} />
                  </button>
                  <span className="flex-1 text-center text-white text-sm font-bold font-mono">
                    {quantity}
                  </span>
                  <button
                    onClick={handleIncrement}
                    className="w-10 h-full flex items-center justify-center text-zinc-400 hover:text-[#00f0ff] hover:bg-zinc-900 border-l border-zinc-800 transition-colors"
                  >
                    <IoIosAdd size={16} />
                  </button>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-1 flex-col sm:flex-row gap-4 mt-6 sm:mt-0 items-end">
                <button
                  onClick={handleAddToCart}
                  className="flex-1 h-12 flex items-center justify-center gap-2 bg-[#00f0ff]/10 text-[#00f0ff] border border-[#00f0ff]/30 hover:bg-[#00f0ff] hover:text-black transition-all font-mono text-[10px] font-bold tracking-[0.2em] uppercase w-full"
                >
                  <BsCartPlus size={16} />
                  [AGREGAR_AL_CARRITO]
                </button>
                <button
                  onClick={() => { }}
                  className="flex-1 h-12 flex items-center justify-center gap-2 bg-[#00f0ff] text-black border border-[#00f0ff] hover:bg-black hover:text-[#00f0ff] transition-all font-mono text-[10px] font-bold tracking-[0.2em] uppercase w-full"
                >
                  <BsCartCheck size={16} />
                  [EJECUTAR_COMPRA]
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs Section */}
      <TabsSection product={product} />
    </div>
  );
};

export default DetailsPage;

import React, { useEffect, useRef, useState } from "react";
import { BsGrid, BsList } from "react-icons/bs";
import CardProductList from "../../components/listProducts/CardProductList";
import CardCategoryList from "../../components/listProducts/CardCategoryList";
import CardFilterPrice from "../../components/listProducts/CardFilterPrice";
import CardFilterBrand from "../../components/listProducts/CardFilterBrand";
import { useProductsInfiniteQuery } from "../../hook/queries/useProduct";
import LoadingFallback from "../../../../shared/ui/LoadingFallback";
import { useProductFilters } from "../../hook/queries/useProductFilters";
import { useSearchParams } from "react-router-dom";
import { useCategories } from "../../../categories/hook/queries/useCategory";

const ListProductsPage: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [sortBy, setSortBy] = useState<string>("popularity");
  const itemsPerPage = 4;

  const isInitializedRef = useRef(false);
  const observerTarget = useRef<HTMLDivElement>(null);
  const { data: allCategories } = useCategories();

  // 🎯 Usar el hook de filtros
  const {
    filters,
    selectedBrands,
    priceRange,
    selectedCategoryObj,
    toggleBrand,
    updatePriceRange,
    setCategory,
    clearFilters,
    activeFiltersCount,
  } = useProductFilters();

  useEffect(() => {
    if (!isInitializedRef.current) {
      const categoryFromUrl = searchParams.get('category');
      const brandsFromUrl = searchParams.get('brands');
      const minPriceFromUrl = searchParams.get('minPrice');
      const maxPriceFromUrl = searchParams.get('maxPrice');

      // Inicializar filtros desde URL
      if (categoryFromUrl && allCategories && allCategories.length > 0) {
        const categoryObj = allCategories?.find(c => c?.id === categoryFromUrl);
        if (categoryObj) {
          setCategory(categoryObj);
        }
      }

      if (brandsFromUrl) {
        brandsFromUrl.split(',').forEach(brand => toggleBrand(brand));
      }
      if (minPriceFromUrl || maxPriceFromUrl) {
        updatePriceRange(
          minPriceFromUrl ? Number(minPriceFromUrl) : 0,
          maxPriceFromUrl ? Number(maxPriceFromUrl) : 1000
        );
      }

      isInitializedRef.current = true;
    }
  }, []);

  // ✨ Actualizar URL cuando cambian los filtros
  useEffect(() => {
    if (!isInitializedRef.current) return;

    const params = new URLSearchParams();

    if (filters.category) params.set('category', filters.category);
    if (filters.brands && filters.brands.length > 0) {
      params.set('brands', filters.brands.join(','));
    }
    if (filters.minPrice) params.set('minPrice', filters.minPrice.toString());
    if (filters.maxPrice) params.set('maxPrice', filters.maxPrice.toString());
    if (filters.search) params.set('search', filters.search);

    setSearchParams(params, { replace: true });
  }, [filters]);

  // 🚀 Usar React Query Infinite con los filtros
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    error,
    isFetching
  } = useProductsInfiniteQuery({
    ...filters,
    limit: itemsPerPage,
  });

  // 🔍 Intersection Observer para scroll infinito
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasNextPage && !isFetchingNextPage) {
          fetchNextPage();
        }
      },
      { threshold: 0.5 }
    );

    const currentTarget = observerTarget.current;
    if (currentTarget) {
      observer.observe(currentTarget);
    }

    return () => {
      if (currentTarget) {
        observer.unobserve(currentTarget);
      }
    };
  }, [fetchNextPage, hasNextPage, isFetchingNextPage]);

  // 📦 Combinar todos los productos de todas las páginas
  const allProducts = React.useMemo(() => {
    return data?.pages.flatMap(page => page.data || []) || [];
  }, [data]);

  // 🔢 Calcular total de productos
  const totalProducts = React.useMemo(() => {
    return data?.pages[0]?.total || allProducts.length;
  }, [data, allProducts]);

  // 📊 Ordenar productos según sortBy
  const sortedProducts = React.useMemo(() => {
    if (!allProducts.length) return [];

    const sorted = [...allProducts];

    switch (sortBy) {
      case 'price-low':
        return sorted.sort((a, b) => a.price - b.price);
      case 'price-high':
        return sorted.sort((a, b) => b.price - a.price);
      case 'newest':
        return sorted.sort((a, b) =>
          new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime()
        );
      case 'popularity':
      default:
        return sorted.sort((a, b) => (b.price || 0) - (a.price || 0));
    }
  }, [allProducts, sortBy]);

  if (isLoading) return <LoadingFallback />

  if (error) return <div className="text-red-500 text-center py-8">{error.message}</div>

  return (
    <div className="min-h-screen bg-[#020202] relative font-mono text-white">
      {/* Elemento decorativo de fondo */}
      <div
        className="fixed inset-0 pointer-events-none opacity-[0.03] z-0"
        style={{
          backgroundImage: `
            linear-gradient(to right, #ffffff 1px, transparent 1px),
            linear-gradient(to bottom, #ffffff 1px, transparent 1px)
          `,
          backgroundSize: '40px 40px'
        }}
      />

      <div className="max-w-7xl mx-auto px-4 py-8 relative z-10">
        <div className="flex flex-col lg:flex-row gap-8">
          {/* Sidebar Filters */}
          <div className="lg:w-64 shrink-0 space-y-6">
            {activeFiltersCount > 0 && (
              <div className="bg-[#050505] border border-zinc-800 p-4 relative mb-6">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-bold text-[#e4ff00] tracking-[0.2em] uppercase flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-[#e4ff00] animate-pulse"></span>
                    FILTROS ACTIVOS ({activeFiltersCount})
                  </span>
                  <button
                    onClick={clearFilters}
                    className="text-[10px] text-zinc-500 hover:text-[#ff0055] font-bold tracking-widest uppercase transition-colors"
                  >
                    [CLR_ALL]
                  </button>
                </div>

                {/* Chips de marcas seleccionadas */}
                {selectedBrands.length > 0 && (
                  <div className="flex flex-wrap gap-2 mb-2">
                    {selectedBrands.map(brand => (
                      <span
                        key={brand}
                        onClick={() => toggleBrand(brand)}
                        className="inline-flex items-center gap-1 px-2 py-1 bg-[#00f0ff]/10 border border-[#00f0ff]/30 text-[#00f0ff] text-[10px] font-bold tracking-[0.15em] uppercase cursor-pointer hover:bg-[#ff0055]/10 hover:border-[#ff0055] hover:text-[#ff0055] transition-all"
                      >
                        {brand}
                        <button className="text-zinc-500 hover:text-[#ff0055] ml-1">×</button>
                      </span>
                    ))}
                  </div>
                )}

                {/* Chip de categoría */}
                {selectedCategoryObj && (
                  <span
                    onClick={() => setCategory(undefined)}
                    className="inline-flex items-center gap-1 px-2 py-1 bg-[#e4ff00]/10 border border-[#e4ff00]/30 text-[#e4ff00] text-[10px] font-bold tracking-[0.15em] uppercase cursor-pointer hover:bg-[#ff0055]/10 hover:border-[#ff0055] hover:text-[#ff0055] transition-all mb-2"
                  >
                    CAT_ {selectedCategoryObj.name}
                    <button className="text-zinc-500 hover:text-[#ff0055] ml-1">×</button>
                  </span>
                )}

                {/* Chip de precio */}
                {(filters.minPrice || filters.maxPrice || filters.minPrice === 0) && (
                  <span
                    onClick={() => updatePriceRange(0, 1000000)}
                    className="inline-flex items-center gap-1 px-2 py-1 bg-zinc-900 border border-zinc-700 text-zinc-300 text-[10px] font-bold tracking-[0.15em] uppercase cursor-pointer hover:bg-[#ff0055]/10 hover:border-[#ff0055] hover:text-[#ff0055] transition-all"
                  >
                    CR_{filters.minPrice || 0} - CR_{filters.maxPrice || 1000000}
                    <button className="text-zinc-500 hover:text-[#ff0055] ml-1">×</button>
                  </span>
                )}
              </div>
            )}

            {/* Categories */}
            <CardCategoryList
              selectedCategory={filters.category}
              onSelectCategory={setCategory}
            />

            {/* Price Filter */}
            <CardFilterPrice
              priceRange={priceRange}
              onPriceChange={updatePriceRange}
            />

            {/* Brand Filter */}
            <CardFilterBrand
              selectedBrands={selectedBrands}
              onToggleBrand={toggleBrand}
            />
          </div>

          {/* Main Content */}
          <div className="flex-1">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6 border-b border-zinc-800 pb-4">
              <p className="text-zinc-500 text-[10px] uppercase tracking-[0.2em] font-bold">
                RENDERIZADOS <span className="text-white">{sortedProducts.length}</span> DE{" "}
                <span className="text-[#00f0ff]">
                  {totalProducts} RESULTADOS
                </span>
                {isFetching && (
                  <span className="ml-3 text-[#e4ff00] animate-pulse inline-flex items-center gap-1">
                    <span className="w-1.5 h-1.5 bg-[#e4ff00]"></span>
                    [ACTUALIZANDO_BASE_DE_DATOS...]
                  </span>
                )}
              </p>

              <div className="flex items-center gap-6">
                <div className="flex items-center gap-3">
                  <span className="text-zinc-600 text-[10px] font-bold tracking-[0.2em] uppercase hidden sm:block">SORT_ORDER:</span>
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                    className="bg-[#050505] border border-zinc-800 text-[#00f0ff] px-3 py-2 text-xs font-bold tracking-[0.1em] uppercase outline-none focus:border-[#00f0ff] cursor-pointer appearance-none hover:border-zinc-600 transition-colors"
                  >
                    <option value="popularity">POPULARIDAD</option>
                    <option value="price-low">PRECIO_ASC</option>
                    <option value="price-high">PRECIO_DESC</option>
                    <option value="newest">MÁS_RECENTES</option>
                  </select>
                </div>

                <div className="flex gap-2 bg-[#050505] border border-zinc-800 p-1">
                  <button
                    onClick={() => setViewMode("grid")}
                    className={`p-1.5 transition-all ${viewMode === "grid"
                      ? "bg-[#00f0ff]/20 text-[#00f0ff]"
                      : "bg-transparent text-zinc-600 hover:text-zinc-300"
                      }`}
                  >
                    <BsGrid size={14} />
                  </button>
                  <button
                    onClick={() => setViewMode("list")}
                    className={`p-1.5 transition-all ${viewMode === "list"
                      ? "bg-[#00f0ff]/20 text-[#00f0ff]"
                      : "bg-transparent text-zinc-600 hover:text-zinc-300"
                      }`}
                  >
                    <BsList size={14} />
                  </button>
                </div>
              </div>
            </div>

            {/* Products Grid */}
            {sortedProducts.length > 0 ? (
              <>
                <div
                  className={`grid gap-6 mb-8 ${viewMode === "grid"
                    ? "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3"
                    : "grid-cols-1"
                    }`}
                >
                  {sortedProducts.map((product) => (
                    <CardProductList
                      key={product.id}
                      product={product}
                      viewMode={viewMode}
                    />
                  ))}
                </div>

                {/* 🎯 Elemento observer para scroll infinito */}
                <div
                  ref={observerTarget}
                  className="h-20 flex justify-center items-center my-4"
                >
                  {isFetchingNextPage && (
                    <div className="flex items-center gap-3 text-[#00f0ff] uppercase text-[10px] font-bold tracking-widest">
                      <div className="w-3 h-3 border border-[#00f0ff] border-t-transparent animate-spin"></div>
                      <span>[CARGANDO_REGISTROS_ADICIONALES...]</span>
                    </div>
                  )}
                </div>

                {/* Mensaje de fin */}
                {!hasNextPage && sortedProducts.length > 0 && (
                  <div className="text-center text-zinc-600 py-8 border-t border-zinc-900 border-dashed uppercase text-[10px] font-bold tracking-[0.2em]">
                    <p>
                      FIN_DE_RESULTADOS: {sortedProducts.length} REGISTROS COMPLETADOS
                    </p>
                  </div>
                )}
              </>
            ) : (
              <div className="text-center py-20 border border-zinc-800 bg-[#050505] relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-[1px] bg-[linear-gradient(90deg,transparent,#ff0055,transparent)] opacity-20"></div>

                <h2 className="text-[#ff0055] text-xs font-bold tracking-[0.2em] uppercase mb-2 flex items-center justify-center gap-2">
                  <div className="w-2 h-2 bg-[#ff0055] animate-ping"></div>
                  [ERROR: LA_CONSULTA_DEVUELVE_NULL]
                </h2>
                <p className="text-zinc-500 text-[10px] tracking-widest uppercase mb-8">
                  NO_HAY_PRODUCTOS_CON_ESTOS_FILTROS
                </p>
                <button
                  onClick={clearFilters}
                  className="px-8 py-3 bg-[#00f0ff]/10 text-[#00f0ff] font-bold tracking-[0.2em] uppercase text-[10px] hover:bg-[#00f0ff] hover:text-black border border-[#00f0ff]/30 transition-all"
                >
                  [RESET_SYS_FILTERS]
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ListProductsPage;

import { FaCity } from "react-icons/fa";
import { PiCityFill } from "react-icons/pi";
import { FaMapLocationDot } from "react-icons/fa6";
import { MdLocationCity } from "react-icons/md";
import useInputs from "../../../shared/hooks/useInputs";
import { BiMap, BiSave } from "react-icons/bi";
import type { User } from "../../auth/types/auth.types";
import MiModal from "../../../shared/ui/Modal";
import { useEffect, useState } from "react";
import { AxiosError } from "axios";
import { toast } from "sonner";
import { useUpdateAddressMutation } from "../hook/mutation/useProfileMutation";

interface ModalAddressProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    data: User | undefined;
}

const ModalAddress: React.FC<ModalAddressProps> = ({ isOpen, onClose, data }) => {
    const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
    const updateAddressMutation = useUpdateAddressMutation();
    const [editAddress, onChangeEditAddress, setEditAddress] = useInputs({
        id: data?.addresses![0].id,
        city: "",
        state: "",
        street: "",
        country: "",
        zipCode: "",
        fullName: null,
        phone: null,
        isDefault: true
    })

    useEffect(() => {
        setEditAddress({
            id: data?.addresses![0].id,
            city: data?.addresses![0].city,
            state: data?.addresses![0].state,
            street: data?.addresses![0].street,
            country: data?.addresses![0].country,
            zipCode: data?.addresses![0].zipCode,
            fullName: null,
            phone: null,
            isDefault: true
        })
    }, [data])

    const handleSubmit = async (e?: React.FormEvent<HTMLButtonElement>) => {
        e?.preventDefault();
        setIsSubmitting(true);
        try {
            await updateAddressMutation.mutateAsync({ id: editAddress.id, addressData: editAddress });
        } catch (error) {
            if (error instanceof AxiosError && error.response?.data?.errors) {
                toast.error(error.response.data.errors);
            }
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <MiModal
            isOpen={isOpen}
            onClose={onClose}
            title={`> [EDITAR_COORDINADAS]`}
        >
            <form className="w-full h-[400px] mb-15 overflow-y-scroll text-left font-mono">
                <div className="mb-8">
                    <h2 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-2 mb-6">
                        <span className="text-[#00f0ff]">{'>'}</span> [DATOS_DE_UBICACIÓN]
                    </h2>

                    <div className="flex flex-col sm:flex-row gap-4 mb-4">
                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [DIRECCIÓN_DE_CALLE]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <BiMap size={18} className="text-zinc-600" />
                                <input type="text" name="street" placeholder="[INTRODUCIR_DIRECCIÓN]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editAddress.street} onChange={onChangeEditAddress} required />
                            </div>
                        </div>

                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [SECTOR_DE_LA_CIUDAD]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <MdLocationCity size={18} className="text-zinc-600" />
                                <input type="text" name="city" placeholder="[INTRODUCIR_CIUDAD]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editAddress.city} onChange={onChangeEditAddress} required />
                            </div>
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-4 mb-4">
                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [ESTADO_O_REGIÓN]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <PiCityFill size={18} className="text-zinc-600" />
                                <input type="text" name="state" placeholder="[INTRODUCIR_ESTADO]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editAddress.state} onChange={onChangeEditAddress} required />
                            </div>
                        </div>

                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [TERRITORIO]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <FaCity size={18} className="text-zinc-600" />
                                <input type="text" name="country" placeholder="[INTRODUCIR_TERRITORIO]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editAddress.country} onChange={onChangeEditAddress} required />
                            </div>
                        </div>
                    </div>

                    <div className="w-full">
                        <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                            [CÓDIGO_POSTAL]
                        </label>
                        <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                            <FaMapLocationDot size={18} className="text-zinc-600" />
                            <input type="text" name="zipCode" placeholder="[INTRODUCIR_CÓDIGO_POSTAL]"
                                className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                value={editAddress.zipCode} onChange={onChangeEditAddress} required />
                        </div>
                    </div>
                </div>

                <div className="flex gap-2 w-full mt-8">
                    <button
                        type="button"
                        onClick={onClose}
                        className="flex-1 bg-black border border-zinc-800 hover:border-zinc-500 text-zinc-400 hover:text-white h-12 font-black uppercase tracking-widest text-xs transition-colors"
                    >
                        [CANCELAR]
                    </button>
                    <button
                        onClick={handleSubmit}
                        type="submit"
                        disabled={isSubmitting}
                        className="flex-1 bg-[#050505] border border-[#00f0ff] hover:bg-[#00f0ff] text-[#00f0ff] hover:text-black h-12 font-black uppercase tracking-widest text-xs transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isSubmitting ? (
                            <div className="animate-spin h-4 w-4 border-2 border-current border-t-transparent rounded-full" />
                        ) : (
                            <>
                                <BiSave size={16} />
                                [GUARDAR_DATOS]
                            </>
                        )}
                    </button>
                </div>
            </form>
        </MiModal>
    )
}
export default ModalAddress

import MiModal from "../../../shared/ui/Modal";
import { BiPhone, BiSave, BiUser } from "react-icons/bi";
import type { User } from "../../auth/types/auth.types";
import useInputs from "../../../shared/hooks/useInputs";
import { useEffect, useState } from "react";
import { useUpdateUserMutation } from "../../auth/hooks/mutation/useAuthMutation";
import { AxiosError } from "axios";
import { toast } from "sonner";

interface ModalInfoProps {
    isOpen: boolean;
    onClose: () => void;
    data: User | undefined;
}
const ModalInfo: React.FC<ModalInfoProps> = ({ isOpen, onClose, data }) => {
    const updateUserMutation = useUpdateUserMutation();
    const [isSubmitting, setIsSubmitting] = useState<boolean>(false);

    const [editProfile, onChangeEditProfile, setEditProfile] = useInputs({
        firstName: "",
        lastName: "",
        phone: ""
    })

    useEffect(() => {
        setEditProfile({
            firstName: data?.firstName,
            lastName: data?.lastName,
            phone: data?.phone
        })
    }, [data])

    const handleSubmit = async (e?: React.FormEvent<HTMLButtonElement>) => {
        e?.preventDefault();
        setIsSubmitting(true);
        try {
            await updateUserMutation.mutateAsync({ id: data?.id!, userData: editProfile });

        } catch (error) {
            if (error instanceof AxiosError && error.response?.data?.errors) {
                toast.error(error.response.data.errors);
            }
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <MiModal
            isOpen={isOpen}
            onClose={onClose}
            title={`> [EDITAR_PERFIL]`}
        >
            <form className="w-full text-left font-mono">
                <div className="mb-8">
                    <h2 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-2 mb-6">
                        <span className="text-[#00f0ff]">{'>'}</span> [DATOS_PERSONALES]
                    </h2>

                    <div className="flex flex-col sm:flex-row gap-4 mb-4">
                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [NOMBRE]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <BiUser size={18} className="text-zinc-600" />
                                <input type="text" name="firstName" placeholder="[INTRODUCIR_NOMBRE]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editProfile.firstName} onChange={onChangeEditProfile} required />
                            </div>
                        </div>

                        <div className="w-full">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                                [APELLIDO]
                            </label>
                            <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                                <BiUser size={18} className="text-zinc-600" />
                                <input type="text" name="lastName" placeholder="[INTRODUCIR_APELLIDO]"
                                    className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                    value={editProfile.lastName} onChange={onChangeEditProfile} required />
                            </div>
                        </div>
                    </div>

                    <div className="w-full">
                        <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800 mb-1">
                            [COMUNICACIÓN_VOZ]
                        </label>
                        <div className="flex items-center w-full bg-black border border-zinc-800 h-12 overflow-hidden px-4 gap-3 focus-within:border-[#00f0ff] transition-colors">
                            <BiPhone size={18} className="text-zinc-600" />
                            <input type="text" name="phone" placeholder="[INTRODUCIR_TELEFONO]"
                                className="w-full bg-transparent text-white placeholder-zinc-700 border-none outline-none text-xs tracking-widest uppercase font-bold"
                                value={editProfile.phone} onChange={onChangeEditProfile} required />
                        </div>
                    </div>
                </div>

                <div className="flex gap-2 w-full mt-8">
                    <button
                        type="button"
                        onClick={onClose}
                        className="flex-1 bg-black border border-zinc-800 hover:border-zinc-500 text-zinc-400 hover:text-white h-12 font-black uppercase tracking-widest text-xs transition-colors"
                    >
                        [CANCELAR]
                    </button>
                    <button
                        onClick={handleSubmit}
                        type="submit"
                        disabled={isSubmitting}
                        className="flex-1 bg-[#050505] border border-[#00f0ff] hover:bg-[#00f0ff] text-[#00f0ff] hover:text-black h-12 font-black uppercase tracking-widest text-xs transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isSubmitting ? (
                            <div className="animate-spin h-4 w-4 border-2 border-current border-t-transparent rounded-full" />
                        ) : (
                            <>
                                <BiSave size={16} />
                                [GUARDAR_DATOS]
                            </>
                        )}
                    </button>
                </div>
            </form>
        </MiModal>
    )
}

export default ModalInfo

