import { BiLock } from "react-icons/bi";
import useInputs from "../../../shared/hooks/useInputs";
import { useChangePasswordMutation } from "../hook/mutation/useProfileMutation";
import { useAuthStore } from "../../auth/store/useAuthStore";
import { toast } from "sonner";

interface SecurityInfoProps {
    activeTab: "inicio" | "pedidos" | "seguridad" | "preferencias";
}

const SecurityInfo = ({ activeTab }: SecurityInfoProps) => {
    const { user } = useAuthStore();
    const changePasswordMutation = useChangePasswordMutation();
    const [passwords, onChangePasswords, setPasswords] = useInputs({
        current: "",
        new: "",
        confirm: "",
    });
    const handleChangePassword = async () => {
        if (passwords.new !== passwords.confirm) {
            toast.error("Las contraseñas no coinciden");
            return;
        }

        let data = {
            email: user?.email!,
            otp: user?.otp!,
            password: passwords.current,
            newPassword: passwords.new,
        };

        await changePasswordMutation.mutateAsync(data);
        setPasswords({
            current: "",
            new: "",
            confirm: "",
        });
    };
    return (
        <>
            {activeTab === "seguridad" && (
                <div className="bg-[#050505] border border-zinc-800 p-6 md:p-8 font-mono relative group">
                    <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-zinc-600 group-hover:border-[#FF0055] transition-colors" />

                    <div className="flex items-center justify-between mb-8">
                        <h2 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-2">
                            <span className="text-[#FF0055]">{'>'}</span> [PARAMETROS_DE_SEGURIDAD]
                        </h2>
                    </div>

                    <div className="space-y-6 max-w-xl">
                        <div className="space-y-1">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800">
                                [CONTRASEÑA_ACTUAL]
                            </label>
                            <input
                                type="password"
                                name="current"
                                value={passwords.current}
                                onChange={onChangePasswords}
                                className="w-full bg-black border border-zinc-800 text-white px-4 py-3 outline-none focus:border-[#FF0055] transition-colors font-mono tracking-widest"
                                placeholder="••••••••"
                            />
                        </div>

                        <div className="space-y-1">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800">
                                [NUEVA_CONTRASEÑA]
                            </label>
                            <input
                                type="password"
                                name="new"
                                value={passwords.new}
                                onChange={onChangePasswords}
                                className="w-full bg-black border border-zinc-800 text-white px-4 py-3 outline-none focus:border-[#FF0055] transition-colors font-mono tracking-widest"
                                placeholder="••••••••"
                            />
                        </div>

                        <div className="space-y-1">
                            <label className="block text-zinc-500 text-[10px] font-bold uppercase tracking-widest pl-1 border-l-2 border-zinc-800">
                                [VERIFICAR_NUEVA_CONTRASEÑA]
                            </label>
                            <input
                                type="password"
                                name="confirm"
                                value={passwords.confirm}
                                onChange={onChangePasswords}
                                className="w-full bg-black border border-zinc-800 text-white px-4 py-3 outline-none focus:border-[#FF0055] transition-colors font-mono tracking-widest"
                                placeholder="••••••••"
                            />
                        </div>

                        <button
                            onClick={handleChangePassword}
                            className="w-full bg-[#050505] border border-[#FF0055] hover:bg-[#FF0055] text-[#FF0055] hover:text-black mt-4 py-4 font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                        >
                            <BiLock size={18} />
                            [ACTUALIZAR_CREDENCIA]
                        </button>
                    </div>
                </div>
            )}
        </>
    );
};

export default SecurityInfo;

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { authService } from "../../../auth/services/authService";
import { toast } from "sonner";
import type { ChangePasswordInput, UpdateAddressInput } from "../../types/profile.types";
import { profileService } from "../../services/profileService";

export const useChangePasswordMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (data: ChangePasswordInput) => authService.changePassword(data),
        onSuccess: (response) => {
            queryClient.invalidateQueries({ queryKey: ['profile'] });

            toast.success(response.message || "Contraseña cambiada exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al cambiar la contraseña");
        }
    })
}

export const useUpdateAddressMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ id, addressData }: UpdateAddressInput) => profileService.updateAddress({ id, addressData }),
        onSuccess: (response) => {
            queryClient.invalidateQueries({ queryKey: ['profile'] });
            queryClient.invalidateQueries({ queryKey: ['cart'] });
            queryClient.invalidateQueries({ queryKey: ['address'] });

            toast.success(response.message || "Direccion actualizada exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al actualizar la direccion");
        }
    })
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { showcaseService } from "../../services/showcaseService";
import { toast } from "sonner";
import type { Banner } from "../../types/banner.types";

export const useAddBannerMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ id, banner }: { id: string, banner: Banner }) => showcaseService.updateBanner(id, banner),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['banner'] });
            queryClient.invalidateQueries({ queryKey: ['showcase'] });

            toast.success(response.message || "Banner agregado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al agregar el banner");
        }
    })
}

export const useDeleteBannerMutation = () => {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (id: string) => showcaseService.deleteBanner(id),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['banner'] });
            queryClient.invalidateQueries({ queryKey: ['showcase'] });

            toast.success(response.message || "Banner eliminado exitosamente");
        },
        onError: (error: any) => {
            toast.error(error.response?.data.message || "Error al eliminar el banner");
        }
    })
}

import { BiPackage } from "react-icons/bi";

interface GeneralInformationProps {
    tracking: any;
    onChangeCreateData: (e: React.ChangeEvent<HTMLInputElement>) => void;
}

const GeneralInformation: React.FC<GeneralInformationProps> = ({ tracking, onChangeCreateData }) => {
    return (
        <div className="bg-[#0a0a0a] border border-zinc-800 p-6 relative">
            <div className="absolute top-0 right-0 w-8 h-8 border-t border-r border-[#00f0ff] opacity-50"></div>

            <h2 className="text-sm font-mono tracking-widest uppercase text-zinc-100 mb-6 flex items-center gap-2 border-b border-zinc-800 pb-4">
                <BiPackage size={18} className="text-[#00f0ff]" />
                [INFORMACIÓN_GENERAL]
            </h2>
            <div className="flex flex-col md:flex-row gap-6 space-y-0">
                <div className="w-full">
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [ID_DE_SEGUIMIENTO] *
                    </label>
                    <input
                        type="text"
                        name="trackingNumber"
                        value={tracking.tracking.trackingNumber}
                        onChange={onChangeCreateData}
                        required
                        className="w-full bg-[#050505] border border-zinc-800 text-[#00f0ff] font-mono tracking-wider px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-inner"
                        placeholder="TRK-7D83522A"
                        disabled
                    />
                </div>
                <div className="w-full">
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [REFERENCIA_DE_LA_ORDEN] *
                    </label>
                    <input
                        type="text"
                        name="orderNumber"
                        value={tracking.tracking.orderNumber}
                        onChange={onChangeCreateData}
                        disabled
                        required
                        className="w-full bg-[#050505] border border-zinc-800 text-zinc-300 font-mono tracking-wider px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-inner"
                        placeholder="1Z999AA10123456784"
                    />
                </div>
            </div>
        </div>
    );
};

export default GeneralInformation;

import moment from "moment";

interface MetadataProps {
    metadata: any;
}

const Metadata: React.FC<MetadataProps> = ({ metadata }) => {
    return (
        <div className="bg-[#0a0a0a] border border-zinc-800 p-6 relative">
            <h3 className="text-[10px] font-mono font-bold text-zinc-600 uppercase tracking-widest mb-4 border-b border-zinc-800 pb-2">[METADATOS_DEL_SISTEMA]</h3>

            <div className="space-y-4 text-xs font-mono tracking-wider">
                <div className="flex justify-between items-center bg-[#050505] border border-zinc-800 px-3 py-2">
                    <span className="text-zinc-500 uppercase">[CREADO_EL]</span>
                    <span className="text-zinc-300">{moment(metadata?.data?.createdAt).format('DD/MM/YYYY')}</span>
                </div>
                <div className="flex justify-between items-center bg-[#050505] border border-zinc-800 px-3 py-2">
                    <span className="text-zinc-500 uppercase">[ÚLTIMA_MODIFICACIÓN]</span>
                    <span className="text-[#00f0ff]">{moment(metadata?.data?.updatedAt).format('DD/MM/YYYY')}</span>
                </div>
                <div className="flex justify-between items-center px-3 py-2">
                    <span className="text-zinc-500 uppercase text-[10px]">[LINK_DEL_SISTEMA]</span>
                    <a href="#" className="text-[#e4ff00] hover:text-white flex items-center gap-1 transition-colors uppercase text-[10px] tracking-widest hover:underline">
                        [VER_REGISTROS_DE_API]
                        <span className="text-[10px]">↗</span>
                    </a>
                </div>
            </div>
        </div>
    );
};

export default Metadata;

import { BiCalendar, BiCheckCircle, BiMapPin, BiPackage } from "react-icons/bi";
import { BsTrash2 } from "react-icons/bs";
import { CiLock } from "react-icons/ci";
import ButtonAction from "../../../../shared/ui/ButtonAction";
import { useTrackingEvents } from "../../hook/queries/useTracking";
import { FaCheckCircle } from "react-icons/fa";
import { useUpdateTrackingEventMutation } from "../../hook/mutation/useTrackingMutation";

interface ShowHistoryProps {
    showHistory: boolean;
    trackingId: string;
    setShowHistory: (showHistory: boolean) => void;
    handleDeleteEvent: (id: any) => void;
}
const ShowHistory = ({ showHistory, trackingId, handleDeleteEvent }: ShowHistoryProps) => {
    const { mutate: updateTrackingEvent } = useUpdateTrackingEventMutation(trackingId);
    const { data: trackingEvents } = useTrackingEvents(trackingId);

    const handleCompleteEvent = (id: any) => {
        const eventData = {
            id: id,
            completed: true
        }
        updateTrackingEvent(eventData);
    }

    const events = trackingEvents?.data ?? [];

    const orderedEvents = [...events].sort(
        (a, b) =>
            new Date(b.createdAt).getTime() -
            new Date(a.createdAt).getTime()
    );
    return (
        <div>
            {/* Tracking History */}
            {showHistory && (
                <div className="bg-[#0a0a0a] border border-zinc-800 p-6 relative mt-6">
                    <div className="absolute top-0 right-0 w-8 h-8 border-t border-r border-[#00f0ff] opacity-50"></div>
                    <div className="flex items-center justify-between mb-6 border-b border-zinc-800 pb-4">
                        <h2 className="text-sm font-mono tracking-widest uppercase text-zinc-100">[TELEMETRÍA_DE_SEGUIMIENTO]</h2>
                        <span className="text-[10px] font-mono tracking-widest uppercase text-[#00f0ff] bg-[#00f0ff]/10 px-2 py-1 border border-[#00f0ff]/30">{trackingEvents?.data?.length} EVENTOS_REGISTRADOS</span>
                    </div>

                    <div className="space-y-0">
                        {trackingEvents?.data?.length === 0 ? (
                            <div className="text-center py-8 text-zinc-600 bg-[#050505] border border-zinc-800 border-dashed">
                                <BiPackage className="w-8 h-8 mx-auto mb-3 opacity-50" />
                                <p className="font-mono text-xs tracking-widest uppercase">[NO_HAY_EVENTOS_REGISTRADOS]</p>
                            </div>
                        ) : (
                            orderedEvents.map((event: any) => (
                                <div
                                    key={event.id}
                                    className="relative pl-8 pb-8 border-l border-zinc-700 last:border-l-0 last:pb-0"
                                >
                                    {/* Timeline square node */}
                                    <div className={`absolute left-0 top-0 -translate-x-[5px] w-2.5 h-2.5 border flex items-center justify-center ${event.completed
                                        ? 'bg-[#e4ff00] border-[#e4ff00]'
                                        : 'bg-[#00f0ff]/20 border-[#00f0ff]'
                                        }`}></div>

                                    <div className="bg-[#050505] border border-zinc-800 p-4 hover:border-zinc-600 transition-colors group relative">
                                        {/* Corner Accents */}
                                        <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-zinc-700 opacity-50"></div>
                                        <div className="absolute bottom-0 right-0 w-2 h-2 border-b border-r border-zinc-700 opacity-50"></div>

                                        <div className="flex items-start justify-between mb-3 border-b border-zinc-900 pb-3">
                                            <div>
                                                <h3 className="font-mono text-sm font-bold text-zinc-100 tracking-wider uppercase flex items-center gap-2">
                                                    <span className={`${event.completed ? 'text-[#e4ff00]' : 'text-[#00f0ff]'}`}>&gt;</span>
                                                    [{event.status}]
                                                </h3>
                                                <div className="flex items-center gap-2 text-[10px] font-mono text-zinc-500 uppercase tracking-widest mt-1">
                                                    <BiMapPin className="w-3 h-3 text-zinc-400" />
                                                    <span>{event.location}</span>
                                                </div>
                                            </div>
                                            <div className="flex flex-row items-center gap-1">
                                                <ButtonAction
                                                    onClick={() => handleCompleteEvent(event.id)}
                                                    variant="secondary"
                                                    text=""
                                                    className="p-1 border border-zinc-800 bg-transparent text-zinc-500 hover:text-[#e4ff00] hover:border-[#e4ff00] transition-colors rounded-none"
                                                >
                                                    <FaCheckCircle className="w-4 h-4" />
                                                </ButtonAction>
                                                <ButtonAction
                                                    onClick={() => handleDeleteEvent(event.id)}
                                                    variant="danger"
                                                    text=""
                                                    className="p-1 border border-zinc-800 bg-transparent text-zinc-500 hover:text-[#ff0055] hover:border-[#ff0055] transition-colors rounded-none"
                                                >
                                                    <BsTrash2 className="w-4 h-4" />
                                                </ButtonAction>
                                            </div>
                                        </div>

                                        <p className="font-mono text-[11px] text-zinc-400 mb-4 leading-relaxed uppercase tracking-wider pl-4 border-l border-zinc-800">
                                            {event.description}
                                        </p>

                                        <div className="flex items-center gap-4 text-[10px] font-mono text-zinc-600 uppercase tracking-widest">
                                            <div className="flex items-center gap-1 bg-black px-2 py-1 border border-zinc-900">
                                                <BiCalendar className="w-3 h-3 text-zinc-500" />
                                                <span>{event.date}</span>
                                            </div>
                                            <div className="flex items-center gap-1 bg-black px-2 py-1 border border-zinc-900">
                                                <CiLock className="w-3 h-3 text-zinc-500" />
                                                <span>{event.time}</span>
                                            </div>
                                            {event.completed && (
                                                <span className="flex items-center gap-1 text-[#e4ff00] ml-auto">
                                                    <BiCheckCircle className="w-3 h-3" />
                                                    [EJECUTADO]
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default ShowHistory;

import { BiLoader, BiPlus } from "react-icons/bi";

interface TrackingEventFormProps {
    currentEvent: {
        status: string;
        description: string;
        location: string;
        date: string;
        time: string;
        completed: boolean;
        order: number;
    };
    setCurrentEvent: (event: any) => void;
    handleSaveEvent: () => void;
    setShowHistory: (value: boolean) => void;
    showHistory: boolean;
    trackingHistory: any;
    //isLoading?: boolean;
}

const TrackingEventForm: React.FC<TrackingEventFormProps> = ({
    currentEvent,
    setCurrentEvent,
    handleSaveEvent,
    setShowHistory,
    showHistory,
    trackingHistory,
    //isLoading = false
}) => {

    const handleChange = (field: string, value: any) => {
        setCurrentEvent({
            ...currentEvent,
            [field]: value
        });
    };

    const isFormValid = currentEvent.location && currentEvent.description;

    return (
        <div className="bg-[#0a0a0a] border border-zinc-800 p-6 relative">
            <div className="absolute top-0 right-0 w-8 h-8 border-t border-r border-[#00f0ff] opacity-50"></div>

            <div className="flex items-center justify-between mb-6 pb-4 border-b border-zinc-800">
                <div className="flex items-center gap-2">
                    <div className={`w-6 h-6 border border-[#00f0ff] flex items-center justify-center bg-[#00f0ff]/10`}>
                        <BiLoader className="w-3.5 h-3.5 animate-spin text-[#00f0ff]" />
                    </div>
                    <h2 className="text-sm font-mono tracking-widest uppercase text-zinc-100">[NUEVO_EVENTO_DE_TELEMETRÍA]</h2>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [ESTADO_LOGÍSTICO_ACTUAL] *
                    </label>
                    <select
                        value={currentEvent.status}
                        onChange={(e) => handleChange('status', e.target.value)}
                        className="w-full bg-[#050505] border border-zinc-800 text-zinc-100 font-mono tracking-wider px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all appearance-none cursor-pointer"
                    >
                        <option value="CONFIRMED" className="bg-black">[CONFIRMADO]</option>
                        <option value="PROCESSING" className="bg-black">[EN_PROCESO]</option>
                        <option value="SHIPPED" className="bg-black">[ENVIADO]</option>
                        <option value="DELIVERED" className="bg-black">[ENTREGADO]</option>
                        <option value="CANCELLED" className="bg-black">[CANCELADO]</option>
                        <option value="REFUNDED" className="bg-black">[REEMBOLSADO]</option>
                    </select>
                </div>
                <div>
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [UBICACIÓN_DEL_NODO_ACTUAL] *
                    </label>
                    <div className="relative">
                        <input
                            type="text"
                            value={currentEvent.location}
                            onChange={(e) => handleChange('location', e.target.value)}
                            className="w-full bg-[#050505] border border-zinc-800 text-zinc-100 font-mono tracking-wider placeholder-zinc-700 px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all shadow-inner"
                            placeholder="[INPUT_LOCATION]"
                        />
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [FECHA_DEL_EVENTO]
                    </label>
                    <div className="relative">
                        <input
                            type="date"
                            value={currentEvent.date}
                            onChange={(e) => handleChange('date', e.target.value)}
                            className="w-full bg-[#050505] border border-zinc-800 text-[#00f0ff] font-mono tracking-wider px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all cursor-pointer"
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                        [MARCA_DE_TIEMPO_DEL_EVENTO]
                    </label>
                    <div className="relative">
                        <input
                            type="time"
                            value={currentEvent.time}
                            onChange={(e) => handleChange('time', e.target.value)}
                            className="w-full bg-[#050505] border border-zinc-800 text-[#00f0ff] font-mono tracking-wider px-4 py-3 outline-none focus:border-[#00f0ff] focus:bg-black transition-all cursor-pointer"
                        />
                    </div>
                </div>
            </div>

            <div className="mb-6">
                <label className="block text-zinc-500 font-mono text-[10px] tracking-widest uppercase mb-2">
                    [DESCRIPCIÓN_DEL_REGISTRO_DE_ESTADO] *
                </label>
                <textarea
                    value={currentEvent.description}
                    onChange={(e) => handleChange('description', e.target.value)}
                    className="w-full bg-[#050505] border border-zinc-800 text-zinc-100 font-mono tracking-wider placeholder-zinc-700 px-4 py-4 focus:outline-none focus:border-[#00f0ff] focus:bg-black transition-all min-h-[100px] resize-none disabled:opacity-50 disabled:cursor-not-allowed shadow-inner"
                    placeholder="[INTRODUZCA_LOS_DATOS_DEL_REGISTRO...]"
                />
            </div>

            <div className="flex items-center gap-3 mb-8 bg-[#050505] border border-zinc-800 p-3 w-fit">
                <input
                    type="checkbox"
                    id="completed"
                    checked={currentEvent.completed}
                    onChange={(e) => handleChange('completed', e.target.checked)}
                    className="w-4 h-4 text-[#e4ff00] bg-black border-zinc-600 rounded-none focus:ring-[#e4ff00] focus:ring-1 appearance-none checked:bg-[#e4ff00] checked:border-[#e4ff00] transition-colors cursor-pointer"
                />
                <label htmlFor="completed" className="text-zinc-400 font-mono text-xs uppercase tracking-widest cursor-pointer">
                    [MARCAR_NODO_COMO_COMPLETADO]
                </label>
            </div>

            <div className="w-full flex justify-end gap-3 border-t border-zinc-800 pt-6">
                <button
                    onClick={handleSaveEvent}
                    disabled={!isFormValid}
                    className="flex items-center justify-center gap-2 bg-[#00f0ff]/10 border border-[#00f0ff] text-[#00f0ff] font-mono hover:bg-[#00f0ff] hover:text-black transition-colors px-6 py-2 uppercase tracking-widest text-xs disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <BiPlus className="w-4 h-4" />
                    [REGISTRAR_EVENTO]
                </button>
                <button
                    onClick={(e) => { e.preventDefault(); setShowHistory(!showHistory); }}
                    className="flex items-center justify-center gap-2 bg-transparent border border-zinc-700 text-zinc-400 font-mono hover:border-zinc-500 hover:text-zinc-200 transition-colors px-6 py-2 uppercase tracking-widest text-xs"
                >
                    {showHistory ? '[OCULTAR_REGISTROS]' : '[VER_REGISTROS]'} ({trackingHistory?.data?.events?.length || 0})
                </button>
            </div>
        </div>
    );
};

export default TrackingEventForm;

import { BiCheckCircle, BiMapPin, BiPackage, BiTime } from "react-icons/bi";
import { FaBoxOpen, FaShippingFast } from "react-icons/fa";
import { IoLocationSharp } from "react-icons/io5";
import { MdLocalShipping, MdOutlineWarehouse } from "react-icons/md";

interface TrackingTimeLineProps {
    trackingHistory: any;
}

const TrackingTimeLine: React.FC<TrackingTimeLineProps> = ({ trackingHistory }) => {

    const getStatusIcon = (index: number) => {
        const icons = [
            <BiCheckCircle size={24} />,
            <FaBoxOpen size={24} />,
            <MdOutlineWarehouse size={24} />,
            <MdLocalShipping size={24} />,
            <FaShippingFast size={24} />,
            <IoLocationSharp size={24} />,
        ];
        return icons[index] || <BiPackage size={24} />;
    };

    const events = trackingHistory?.data?.events ?? [];

    const orderedEvents = [...events].sort(
        (a, b) =>
            new Date(b.createdAt).getTime() -
            new Date(a.createdAt).getTime()
    );

    return (
        <div className="lg:col-span-2">
            <div className="bg-[#050505] border border-zinc-800 p-6 relative">
                {/* Decorative Elements */}
                <div className="absolute top-0 right-0 w-32 h-1 bg-[#00f0ff] opacity-20"></div>
                <div className="absolute bottom-0 left-0 w-32 h-1 bg-[#00f0ff] opacity-20"></div>

                <h2 className="text-sm font-mono tracking-widest uppercase text-zinc-100 mb-8 flex items-center gap-2 border-b border-zinc-800 pb-4">
                    <span className="text-[#00f0ff]">&gt;</span> [HISTORIAL_DE_TRANSITO]
                </h2>

                <div className="space-y-0">
                    {orderedEvents.map((event: any, index: number) => (
                        <div key={event.id} className="flex gap-6 relative group">
                            {/* Timeline Icon */}
                            <div className="flex flex-col items-center relative z-10 w-12 shrink-0">
                                <div
                                    className={`w-10 h-10 border border-zinc-800 flex items-center justify-center transition-all ${event.completed
                                        ? "bg-[#00f0ff]/10 text-[#00f0ff] border-[#00f0ff]"
                                        : "bg-[#0a0a0a] text-zinc-600"
                                        }`}
                                >
                                    {getStatusIcon(index)}
                                </div>
                                {index < trackingHistory.data.events.length - 1 && (
                                    <div
                                        className={`w-[1px] h-full absolute top-10 ${event.completed ? "bg-[#00f0ff]/50" : "bg-zinc-800 border-dashed border-l border-zinc-700 bg-transparent"
                                            }`}
                                    ></div>
                                )}
                            </div>
                            {/* Event Details */}
                            <div className="flex-1 pb-10">
                                <div className={`border border-zinc-800 bg-[#0a0a0a] p-4 group-hover:bg-[#00f0ff]/5 transition-colors relative ${event.completed ? "border-l-2 border-l-[#00f0ff]" : "border-l-2 border-l-zinc-700"}`}>
                                    <div className="flex justify-between items-start mb-2">
                                        <h3
                                            className={`font-mono text-sm tracking-widest uppercase ${event.completed ? "text-zinc-100" : "text-zinc-500"
                                                }`}
                                        >
                                            [{event.status}]
                                        </h3>
                                        {event.completed && (
                                            <span className="text-[#00f0ff] font-mono text-[10px] tracking-widest uppercase animate-pulse border border-[#00f0ff]/30 px-2 py-0.5">
                                                [VERIFICADO]
                                            </span>
                                        )}
                                    </div>
                                    <p
                                        className={`text-xs mb-3 font-mono tracking-wide ${event.completed ? "text-zinc-400" : "text-zinc-600"
                                            }`}
                                    >
                                        &gt; {event.description}
                                    </p>
                                    <div className="flex items-center gap-6 text-[10px] font-mono tracking-widest uppercase">
                                        <span
                                            className={`flex items-center gap-2 ${event.completed ? "text-zinc-300" : "text-zinc-600"
                                                }`}
                                        >
                                            <BiMapPin size={12} className={event.completed ? "text-[#e4ff00]" : "text-zinc-600"} />
                                            LOC: {event.location}
                                        </span>
                                        <span
                                            className={`flex items-center gap-2 ${event.completed ? "text-zinc-300" : "text-zinc-600"
                                                }`}
                                        >
                                            <BiTime size={12} className={event.completed ? "text-[#e4ff00]" : "text-zinc-600"} />
                                            T: {event.date} | {event.time}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default TrackingTimeLine;

import { useMutation } from "@tanstack/react-query";
import type { TrackingData, TrackingEventData } from "../../types/tracking.types";
import { handleApiError } from "../../../../shared/lib/errorHandler";
import { toast } from "sonner";
import { trackingService } from "../../service/trackingService";
import { queryClient } from "../../../../shared/lib/queryClient";

// Hook para crear/actualizar tracking
export const useTrackingMutation = () => {
    const mutation = useMutation({
        mutationFn: (trackingData: TrackingData) => trackingService.createTracking(trackingData),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['tracking'] });
            toast.success(response.message || 'Seguimiento creado exitosamente');
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al crear el seguimiento');
        }
    });
    return mutation;
};

// Hook para crear eventos de tracking
export const useTrackingEventMutation = (trackingId: string) => {
    const mutation = useMutation({
        mutationFn: (eventData: TrackingEventData) =>
            trackingService.createTrackingEvent(trackingId, eventData),
        onSuccess: (response: any) => {
            // Invalida la query específica del tracking
            queryClient.invalidateQueries({ queryKey: ['tracking', trackingId] });
            queryClient.invalidateQueries({ queryKey: ['tracking-events', trackingId] });
            toast.success(response.message || 'Evento de seguimiento agregado exitosamente');
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al agregar el evento de seguimiento');
        }
    });
    return mutation;
};

// Hook para actualizar tracking
export const useUpdateTrackingMutation = (trackingId: string) => {
    const mutation = useMutation({
        mutationFn: (trackingData: Partial<TrackingData>) =>
            trackingService.updateTracking(trackingId, trackingData),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['tracking', trackingId] });
            queryClient.invalidateQueries({ queryKey: ['tracking-events', trackingId] });
            toast.success(response.message || 'Seguimiento actualizado exitosamente');
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al actualizar el seguimiento');
        }
    });
    return mutation;
};

// Hook para eliminar un evento
export const useDeleteTrackingEventMutation = (trackingId: string) => {
    const mutation = useMutation({
        mutationFn: (eventId: string) =>
            trackingService.deleteTrackingEvent(trackingId, eventId),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['tracking', trackingId] });
            queryClient.invalidateQueries({ queryKey: ['tracking-events', trackingId] });
            toast.success(response.message || 'Evento eliminado exitosamente');
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al eliminar el evento');
        }
    });
    return mutation;
};

export const useUpdateTrackingEventMutation = (trackingId: string) => {
    const mutation = useMutation({
        mutationFn: (eventData: Partial<TrackingEventData>) =>
            trackingService.updateTrackingEvent(trackingId, eventData.id!, eventData),
        onSuccess: (response: any) => {
            queryClient.invalidateQueries({ queryKey: ['tracking', trackingId] });
            queryClient.invalidateQueries({ queryKey: ['tracking-events', trackingId] });
            toast.success(response.message || 'Evento actualizado exitosamente');
        },
        onError: (error: any) => {
            handleApiError(error, 'Error al actualizar el evento');
        }
    });
    return mutation;
};

import { useEffect, useState } from 'react';
import Sidebar from '../../../dashboard/components/Sidebar';
import BreadCrumbs from '../../../../shared/ui/BreadCrumbs';
import NavMobile from '../../../dashboard/components/NavMobile';
import ButtonMobile from '../../../../shared/ui/ButtonMobile';
import DashHeader from '../../../../shared/ui/DashHeader';
import HeaderAction from '../../../auth/components/UserCreate/HeaderAction';
import { MdLocalShipping } from 'react-icons/md';
import GeneralInformation from '../../components/FormCreateTracking/GeneralInformation';
import LogisticDimensions from '../../components/FormCreateTracking/LogisticDimensions';
import TrackingEventForm from '../../components/FormCreateTracking/TrackingEventForm';
import ShowHistory from '../../components/FormCreateTracking/ShowHistory';
import PrioritySettings from '../../components/FormCreateTracking/PrioritySettings';
import Metadata from '../../components/FormCreateTracking/Metadata';
import CurrentTransitView from '../../components/FormCreateTracking/CurrentTransitView';
import useInputs from '../../../../shared/hooks/useInputs';
import { AxiosError } from 'axios';
import {
    useTrackingMutation,
    useTrackingEventMutation,
    useUpdateTrackingMutation,
    useDeleteTrackingEventMutation
} from '../../hook/mutation/useTrackingMutation';
import { useLocation } from 'react-router-dom';
import { useTracking } from '../../hook/queries/useTracking';

interface ValidationErrors {
    [key: string]: string[];
}

const useQuery = () => {
    return new URLSearchParams(useLocation().search);
};

const DashTrackingCreatePage = () => {
    const query = useQuery();
    const orderId = query.get('orderId');
    const trackingNumber = query.get('trackingNumber');

    // Queries y Mutations
    const { data: tracking, isLoading } = useTracking(trackingNumber);
    const createTracking = useTrackingMutation();
    const updateTracking = useUpdateTrackingMutation(trackingNumber!);
    const createEvent = useTrackingEventMutation(tracking?.data?.id!);
    const deleteEvent = useDeleteTrackingEventMutation(tracking?.data?.id!);

    // Estados
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
    const [priority, setPriority] = useState('Medium');
    const [showHistory, setShowHistory] = useState(false);
    const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});

    // Estado principal del tracking
    const [createData, onChangeCreateData, setCreateData] = useInputs({
        orderId: orderId,
        tracking: {
            trackingNumber: trackingNumber,
            orderNumber: "",
            estimatedDelivery: "",
            origin: "",
            destination: "",
            weight: "",
            dimensions: "",
            carrier: "",
            priority: ""
        }
    });

    // Estado separado para el evento actual
    const [currentEvent, setCurrentEvent] = useState({
        status: "CONFIRMED",
        description: "",
        location: "",
        date: "",
        time: "",
        completed: false,
        order: 1
    });

    // Cargar datos del tracking si existe
    useEffect(() => {
        if (tracking && trackingNumber) {
            setCreateData({
                orderId: orderId,
                tracking: {
                    trackingNumber: trackingNumber,
                    orderNumber: tracking?.data?.orderNumber || "",
                    estimatedDelivery: tracking?.data?.estimatedDelivery || "",
                    origin: tracking?.data?.origin || "",
                    destination: tracking?.data?.destination || "",
                    weight: tracking?.data?.weight || "",
                    dimensions: tracking?.data?.dimensions || "",
                    carrier: tracking?.data?.carrier || "",
                    priority: tracking?.data?.priority || ""
                }
            });
        }
    }, [tracking, trackingNumber, orderId]);

    const priorityOptions = [
        { value: 'Medium', label: 'Normal', color: 'bg-emerald-500' },
        { value: 'High', label: 'Fast', color: 'bg-amber-500' },
        { value: 'Urgent', label: 'ASAP', color: 'bg-red-500' }
    ];

    // Guardar o actualizar el tracking (sin eventos)
    const handleSubmit = async (e?: React.MouseEvent<HTMLButtonElement>) => {
        e?.preventDefault();
        setIsSubmitting(true);
        setValidationErrors({});

        try {
            const trackingData = {
                orderId: orderId!,
                tracking: {
                    ...createData.tracking,
                    orderNumber: createData.tracking.orderNumber ||
                        `${Math.floor(Math.random() * 9000000000) + 1000000000}`,
                    priority: priority
                }
            };

            // Si ya existe el tracking, actualizar, si no, crear
            if (tracking.data !== null) {
                await updateTracking.mutateAsync(trackingData);
            } else {
                await createTracking.mutateAsync(trackingData);
            }

            setIsSubmitting(false);
        } catch (error) {
            if (error instanceof AxiosError && error.response?.data?.errors) {
                setValidationErrors(error.response.data.errors);
            }
            setIsSubmitting(false);
        }
    };

    // Guardar un nuevo evento de tracking
    const handleSaveEvent = async () => {

        try {
            await createEvent.mutateAsync({
                ...currentEvent,
                order: (tracking?.events?.length || 0) + 1
            });

            // Resetear el formulario del evento
            setCurrentEvent({
                status: "CONFIRMED",
                description: "",
                location: "",
                date: "",
                time: "",
                completed: false,
                order: 1
            });

            // Mostrar el historial después de guardar
            setShowHistory(true);
        } catch (error) {
            console.error('Error al guardar evento:', error);
        }
    };

    // Eliminar evento del historial
    const handleDeleteEvent = async (eventId: string) => {
        if (!trackingNumber) return;

        try {
            await deleteEvent.mutateAsync(eventId);
        } catch (error) {
            console.error('Error al eliminar evento:', error);
        }
    };

    const handleReset = () => {
        setCreateData({
            orderId: orderId,
            tracking: {
                trackingNumber: trackingNumber,
                orderNumber: "",
                estimatedDelivery: "",
                origin: "",
                destination: "",
                weight: "",
                dimensions: "",
                carrier: "",
                priority: ""
            }
        });
        setCurrentEvent({
            status: "CONFIRMED",
            description: "",
            location: "",
            date: "",
            time: "",
            completed: false,
            order: 1
        });
    };

    const getFieldsError = (fieldName: string): string | undefined => {
        return validationErrors[fieldName]?.[0];
    };

    if (isLoading) {
        return <div className="min-h-screen bg-[#020202] flex items-center justify-center">
            <div className="text-[#00f0ff] font-mono uppercase tracking-widest animate-pulse">[ESTABLISHING_LINK...]</div>
        </div>;
    }

    return (
        <div className="min-h-screen bg-[#020202]">
            <div className='flex'>
                {/* Sidebar */}
                <Sidebar />

                <div className="flex flex-col flex-1">
                    <div className="max-w-7xl px-0 md:px-9">
                        <BreadCrumbs />
                    </div>

                    {/* Mobile Menu */}
                    <NavMobile isMenuOpen={isMenuOpen} setIsMenuOpen={setIsMenuOpen} />

                    <div className="w-full mx-auto flex-1 px-12 pb-8">
                        <ButtonMobile
                            isMenuOpen={isMenuOpen}
                            setIsMenuOpen={setIsMenuOpen}
                        />

                        {/* Header */}
                        <DashHeader
                            data={[]}
                            title={tracking?.data !== null ? "Actualizar Envío" : "Crear Envío"}
                            titleData={tracking?.data !== null ? "Actualizar Envío" : "Crear Envío"}
                            path="tracking"
                            titleIcon={<MdLocalShipping className="text-cyan-400" size={36} />}
                            list={false}
                        />
                        <HeaderAction
                            isSubmitting={isSubmitting}
                            handleSubmit={handleSubmit}
                            handleReset={handleReset}
                        />

                        {/* Form */}
                        <form>
                            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                                {/* Main Content - Left Column */}
                                <div className="col-span-2 space-y-6">
                                    {/* General Information */}
                                    <GeneralInformation
                                        tracking={createData}
                                        onChangeCreateData={onChangeCreateData}
                                    />

                                    {/* Logistics & Dimensions */}
                                    <LogisticDimensions
                                        tracking={createData}
                                        setTracking={setCreateData}
                                        getFieldsError={getFieldsError}
                                    />

                                    {/* Tracking Event Form */}
                                    {
                                        tracking.data !== null && (
                                            <TrackingEventForm
                                                currentEvent={currentEvent}
                                                setCurrentEvent={setCurrentEvent}
                                                handleSaveEvent={handleSaveEvent}
                                                setShowHistory={setShowHistory}
                                                showHistory={showHistory}
                                                trackingHistory={tracking}
                                            //isLoading={createEvent.isPending}
                                            />
                                        )
                                    }

                                    {/* Show History */}
                                    <ShowHistory
                                        showHistory={showHistory}
                                        trackingId={tracking?.data?.id}
                                        setShowHistory={setShowHistory}
                                        handleDeleteEvent={handleDeleteEvent}
                                    />
                                </div>

                                {/* Right Sidebar */}
                                <div className="lg:col-span-1 space-y-6">
                                    <div className="space-y-6">
                                        {/* Priority Settings */}
                                        <PrioritySettings
                                            priority={priority}
                                            setPriority={setPriority}
                                            priorityOptions={priorityOptions}
                                        />

                                        {/* Metadata */}
                                        <Metadata
                                            metadata={tracking}
                                        />

                                        {/* Current Transit View */}
                                        <CurrentTransitView />
                                    </div>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DashTrackingCreatePage;

import React from "react";
import { BiStar, BiX } from "react-icons/bi";
import { CiShoppingCart } from "react-icons/ci";
// Removed duplicate import
